import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"PRD-025 · Finalize the forward roadmap — comprehensive per-agency coverage through ~2035","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-025.md","filePath":"prd/PRD-025.md"}'),n={name:"prd/PRD-025.md"};function s(i,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="prd-025-·-finalize-the-forward-roadmap-—-comprehensive-per-agency-coverage-through-2035" tabindex="-1">PRD-025 · Finalize the forward roadmap — comprehensive per-agency coverage through ~2035 <a class="header-anchor" href="#prd-025-·-finalize-the-forward-roadmap-—-comprehensive-per-agency-coverage-through-2035" aria-label="Permalink to &quot;PRD-025 · Finalize the forward roadmap — comprehensive per-agency coverage through ~2035&quot;">​</a></h1><blockquote><p>Status · Draft (re-scoped for v0.8) · <strong>re-analyzed 2026-07-11</strong> Date · 2026-06-09, re-scoped 2026-07-11 Owner · Marko Closes into · GH epic (v0.8 content track) + per-agency slice PRs · tracking issue #313 Builds on · PRD-004 (Mission Library) · PRD-012 (Spaceflight Fleet) · backlog <code>docs/research/forward-roadmap-2026-07-11.md</code> (comprehensive refresh; supersedes the 2026-06-09 backlog, which is kept for history)</p></blockquote><blockquote><p><strong>What changed on 2026-07-11 (the re-scope).</strong> The original PRD-025 locked a <em>minimum representative cut</em> — 24 missions + ~37 fleet out of ~100 candidates, &quot;≥1 flagship per agency,&quot; with ~75 entries explicitly deferred to &quot;v0.9+&quot;. Marko&#39;s direction: <strong>that&#39;s the wrong frame — finalize each major agency&#39;s forward roadmap comprehensively.</strong> Cover China&#39;s full Moon program, <em>all</em> of Russia&#39;s plans including their own station (ROS), all of ESA&#39;s and JAXA&#39;s roadmaps, ISRO, and the private sector — not one flagship each. This revision reframes the scope from &quot;representative sample&quot; to <strong>per-agency completeness</strong>, refreshes every entry against current (2026-07) data, and defines a tiered finalization scope so the cut line is an explicit decision, not a silent deferral.</p></blockquote><blockquote><p><strong>Why this is a PRD.</strong> Which forward-looking programs and missions Orrery commits to modeling — comprehensively, across every major agency, through ~2035 — is a product-scope decision that gates months of content authoring: mission + fleet JSON, images, 3D scenes, and editorial across 14 locales. Locking the <em>complete</em> set with an explicit, tiered cut line — rather than a silent deferral of everything past one flagship per agency — has to happen before any new entry lands. That scope commitment is why this is a PRD and not a backlog note.</p></blockquote><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>As of today orrery&#39;s <code>static/data/missions/</code> + <code>static/data/fleet/</code> contain <strong>only 7 forward-looking missions and 5 forward-looking fleet entries</strong> against a world that has reset hard: NASA cancelled Gateway and announced a Moon-then-Mars surface-base architecture (&quot;Ignition&quot;, 24 Mar 2026); China merged its crewed-lunar + Chang&#39;e programs and recovered an orbital booster; Russia re-architected ROS around recycled ISS modules; ESA lost its US MSR partner and is debating sovereign crew; ISRO, UAE, Korea, and Brazil are standing up flagship programs and first launches. Orrery&#39;s &quot;what&#39;s planned next&quot; surface is a rounding error against reality. This PRD locks the <strong>complete</strong> forward content set for v0.8 so slices can execute cleanly.</p><h2 id="scope-model-—-per-agency-completeness-tiered" tabindex="-1">Scope model — per-agency completeness, tiered <a class="header-anchor" href="#scope-model-—-per-agency-completeness-tiered" aria-label="Permalink to &quot;Scope model — per-agency completeness, tiered&quot;">​</a></h2><p>Coverage principle: <strong>for each major program, represent its committed forward roadmap in full</strong> — every announced-and-funded element, every in-development flagship, and the program-defining vehicles behind them — rather than a single flagship. Curation still applies at the <code>proposed</code> edge (we don&#39;t model every paper concept), and images/3D remain deferred (content ships with <code>credit</code> first, imagery catches up).</p><p>Three tiers, so the cut line is explicit:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Definition</th><th>Rough new-entry count (missions + fleet, after de-duping the 12 already in data)</th></tr></thead><tbody><tr><td><strong>T1 — Committed</strong></td><td><code>A</code> (announced + funded, hardware/schedule) + the architecture-reset updates to existing entries. The forward roadmap that is actually happening.</td><td>~55–70</td></tr><tr><td><strong>T2 — In-development depth</strong></td><td><code>D</code> (active development) across every program — CLPS deliveries, all ESA science, Luna 26-29, commercial LEO stations, commercial launcher debut wave, megaconstellations. Completes per-agency coverage.</td><td>~60–80</td></tr><tr><td><strong>T3 — Proposed tail</strong></td><td><code>P</code> (study/paper) for the <em>biggest</em> programs only — Neptune orbiter, Venus atmosphere SR, Interstellar Express, Yenisei/Don, Korona, HWO, Enceladus Orbilander, Mangalyaan-2. Selective, not exhaustive.</td><td>~30–45</td></tr></tbody></table><p><strong>Finalization scope (LOCKED 2026-07-11) = T1 + T2 + T3 — everything.</strong> Marko&#39;s call: cover every <code>A</code>/<code>D</code>/<code>P</code> element across all agencies + private sector, including the proposed tail for the big programs. <strong>~180+ new entries.</strong> Full per-item backlog with confidence + <code>→ orrery entry type</code> mapping: <code>docs/research/forward-roadmap-2026-07-11.md</code>.</p><p><strong>Every new entry is authored under a <code>program</code> (see PRD-029).</strong> The forward-roadmap work is the first consumer of the programs grouping layer — author the program (Artemis, Project 921, ILRS, ROS, Gaganyaan, BAS, CLPS, Commercial LEO Destinations, …) then tag its member missions + fleet. Programs are also the coverage lens: a program with a gap in its numbered sequence flags a hole to backfill.</p><h3 id="per-agency-finalization-targets-t1-t2" tabindex="-1">Per-agency finalization targets (T1 + T2) <a class="header-anchor" href="#per-agency-finalization-targets-t1-t2" aria-label="Permalink to &quot;Per-agency finalization targets (T1 + T2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Program family</th><th>New missions</th><th>New fleet</th><th>Notes</th></tr></thead><tbody><tr><td><strong>China</strong> (CNSA/CMSA/CAS + commercial)</td><td>~14</td><td>~20</td><td>Crewed lunar (Mengzhou/Lanyue/Wangyu/Tansuo/CZ-10), ILRS, Chang&#39;e-7/8, Tiangong 6-module + Xuntian + Shenzhou-23/24/25, Tianwen-2/3/4, CZ-9, commercial reusables, Guowang/Qianfan.</td></tr><tr><td><strong>Russia</strong> (Roscosmos)</td><td>~6</td><td>~16</td><td><strong>ROS + 7 modules</strong>, Luna 26-29, Orel, Soyuz-5 (op), Angara A5M/A5V/A5P, Amur, Yenisei, Zeus, Venera-D, Vostochny pads.</td></tr><tr><td><strong>ESA</strong></td><td>~11</td><td>~10</td><td>Plato/Ariel/Comet Interceptor/EnVision/Vigil/LISA/NewAthena/Ramses/SMILE/Plasma Obs, Argonaut, Moonlight, Ariane 6 evolutions, Vega-E, Themis, ELC winners.</td></tr><tr><td><strong>JAXA</strong></td><td>~5</td><td>~5</td><td>MMX (have), LUPEX, DESTINY+, LiteBIRD, Solar-C, Lunar Cruiser, H3, Epsilon S, ispace ULTRA.</td></tr><tr><td><strong>NASA + US commercial</strong></td><td>~18</td><td>~22</td><td>Artemis III(update)/IV/V/VI, Moon Base + Fission Power + LTV, Starship HLS/Blue Moon Mk1-Mk2, SR-1 Freedom, CLPS ×6, Dragonfly/DAVINCI/VERITAS/Roman/NEO Surveyor, Haven-1/2/Axiom/Orbital Reef/Starlab/Gravitics, Starship V3/New Glenn/Neutron/Nova/Terran R/Dream Chaser.</td></tr><tr><td><strong>ISRO + newcomers + private</strong></td><td>~12</td><td>~15</td><td>Gaganyaan G1/H1 + BAS + Chandrayaan-4/5 + Shukrayaan-1 + Mangalyaan-2(P) + NGLV + Skyroot; UAE MBR Explorer/Rashid-2/Airlock; Korea KSLV-III + lander; Brazil VLM-1; newcomer sites + firsts.</td></tr></tbody></table><h2 id="new-categories-schema" tabindex="-1">New categories + schema <a class="header-anchor" href="#new-categories-schema" aria-label="Permalink to &quot;New categories + schema&quot;">​</a></h2><ol><li><strong><code>surface-base</code></strong> fleet category (off-Earth permanent/semi-permanent infrastructure — lunar/Mars bases, surface reactors, ILRS). Distinct from orbital <code>station</code>. Wired in <strong>Slice 0</strong>: add to <code>fleet-entry.schema.json</code> category enum + <code>/fleet</code> filter chip + <code>fleet_category_surface_base</code> i18n keys (en-US, then 14-locale pipeline) + ADR-002 pointer. Entries: NASA Moon Base, Fission Surface Power, ILRS, ILRS nuclear plant.</li><li><strong><code>ground-observatory</code></strong> — already scoped in <strong>PRD-028</strong> (18 Earth-based radio telescopes + DSN); land it in the same v0.8 category-wiring pass as <code>surface-base</code> since both touch the same schema + filter UI.</li></ol><h2 id="architecture-reset-updates-to-existing-entries" tabindex="-1">Architecture-reset updates to existing entries <a class="header-anchor" href="#architecture-reset-updates-to-existing-entries" aria-label="Permalink to &quot;Architecture-reset updates to existing entries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry</th><th>Change</th></tr></thead><tbody><tr><td><code>missions/moon/artemis3</code></td><td>Demote to <strong>LEO HLS-rendezvous demo</strong> (no landing); crew named 9 Jun 2026.</td></tr><tr><td><code>missions/.../artemis4</code></td><td>Confirm as <strong>first crewed landing</strong> (early 2028).</td></tr><tr><td><code>missions/mars/starship-mars-crew</code></td><td>Reframe against the Moon-Base-as-proving-ground architecture.</td></tr><tr><td><code>fleet/.../htv-x</code></td><td>PLANNED → <strong>ACTIVE</strong> (HTV-X1 flew Oct 2025).</td></tr><tr><td><code>fleet/station/tiangong</code></td><td>Add 4th/5th/6th-module expansion timeline (→180t).</td></tr><tr><td><code>fleet/launcher/starship</code></td><td>Cross-link new <code>starship-hls</code> variant + <code>starship-v3</code>.</td></tr><tr><td><code>fleet/launcher/new-glenn</code></td><td>Note LC-36 pad loss (28 May 2026), RTF TBD.</td></tr><tr><td><code>missions/.../apollo-1</code></td><td><strong>Bug:</strong> mis-flagged PLANNED → FLOWN/historical.</td></tr><tr><td>Mars Sample Return, Gateway HALO/I-Hab (if present)</td><td>Mark <strong>CANCELLED / redirected</strong> (<code>grep -rn &#39;mars-sample-return|gateway|halo|i-hab&#39; static/data/</code> at slice start).</td></tr></tbody></table><h2 id="slice-plan-per-agency-program-families" tabindex="-1">Slice plan (per-agency program families) <a class="header-anchor" href="#slice-plan-per-agency-program-families" aria-label="Permalink to &quot;Slice plan (per-agency program families)&quot;">​</a></h2><p>Slice 0 unblocks the new categories; each program-family slice is independent and lands as one PR + one rebase + one preflight. Recommended order puts the architecture resets first (they unblock cross-refs), then the biggest programs.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Slice 0 — Category + schema wiring: surface-base + ground-observatory (schema, /fleet filter, i18n label keys, ADR-002). Fix apollo-1 status bug.</span></span>
<span class="line"><span>Slice 1 — NASA architecture reset: artemis3 demote; Artemis IV/V/VI; Moon Base + Fission Power + LTV; SR-1 Freedom; cancel MSR + Gateway; HLS (Starship HLS, Blue Moon Mk1/Mk2). Updates: htv-x, new-glenn, starship.</span></span>
<span class="line"><span>Slice 2 — China crewed lunar + Tiangong: Mengzhou, Lanyue, Wangyu, Tansuo, CZ-10/10A, Wenchang LC-301, crewed-landing mission; Tiangong 6-module update, Xuntian, Shenzhou-23/24/25, Tianzhou.</span></span>
<span class="line"><span>Slice 3 — China deep-space + ILRS: Tianwen-2/3/4, Chang&#39;e-7/8, planetary-defense demo, ILRS (surface-base) + construction landers + nuclear plant, CZ-9, Queqiao constellation.</span></span>
<span class="line"><span>Slice 4 — Russia: ROS + 7 modules (station + surface reactor context), Luna 26-29, Orel, Soyuz-5, Angara A5M/A5V/A5P, Amur, Yenisei, Zeus, Venera-D, Vostochny pads.</span></span>
<span class="line"><span>Slice 5 — ESA: Plato/Ariel/Comet Interceptor/EnVision/Vigil/LISA/NewAthena/Ramses/SMILE/Plasma Obs; Argonaut, Moonlight; Ariane 6 evolutions, Vega-E, Themis, ELC winners.</span></span>
<span class="line"><span>Slice 6 — JAXA: LUPEX, DESTINY+, LiteBIRD, Solar-C, Lunar Cruiser, H3, Epsilon S, ispace ULTRA.</span></span>
<span class="line"><span>Slice 7 — ISRO: Gaganyaan G1/H1, BAS + modules, Chandrayaan-4/5, Shukrayaan-1, Mangalyaan-2, NGLV, Skyroot Vikram-1.</span></span>
<span class="line"><span>Slice 8 — Newcomers + private: UAE (MBR Explorer, Rashid-2, Airlock), Korea (KSLV-III, lander), Brazil (VLM-1), newcomer launch sites; US commercial LEO stations (Haven-1/2, Axiom, Orbital Reef, Starlab, Gravitics); commercial launcher debut wave (Neutron, Nova, Terran R, Dream Chaser).</span></span>
<span class="line"><span>Slice 9 — NASA planetary + observatories + CLPS: Dragonfly, DAVINCI, VERITAS, Roman, NEO Surveyor; CLPS deliveries (IM-3/4, Blue Ghost 2/3, Griffin-1, APEX).</span></span>
<span class="line"><span>Slice 10 (optional, T3) — Proposed tail for the biggest programs: Neptune orbiter, Venus atmosphere SR, Interstellar Express, HWO, Enceladus Orbilander, Don/Korona.</span></span></code></pre></div><h2 id="effort-—-be-honest" tabindex="-1">Effort — be honest <a class="header-anchor" href="#effort-—-be-honest" aria-label="Permalink to &quot;Effort — be honest&quot;">​</a></h2><p>Per the mission/fleet runbooks each entry is ~8 touchpoints: base JSON + index + en-US overlay + <strong>all-14-locale overlays (now core content, not deferrable)</strong> + ≥3 sourced links + fleet↔mission symmetry + (deferred) imagery. Realistic per-entry authoring is ~30–90 min for fleet, ~45–120 min for missions, plus validate-data iteration.</p><ul><li><strong>T1 + T2 ≈ 135–150 entries.</strong> That is <strong>not a one-sitting job</strong> — it&#39;s ~9 program-family slice PRs, on the order of <strong>1–2 focused days per slice</strong> (editorial care on <code>credit</code>/links + the 14-locale pipeline pass dominate). Call it a multi-week content track, sequenced under Marko&#39;s supervision, one slice at a time.</li><li><strong>T3</strong> adds ~30–45 more; land opportunistically, don&#39;t gate the release on it.</li><li>Imagery is a <strong>separate wave</strong> (Image Pipeline v2) after content; entries ship with <code>credit</code> placeholders, never blocked on images.</li></ul><h2 id="done-definition" tabindex="-1">Done definition <a class="header-anchor" href="#done-definition" aria-label="Permalink to &quot;Done definition&quot;">​</a></h2><h3 id="per-slice" tabindex="-1">Per-slice <a class="header-anchor" href="#per-slice" aria-label="Permalink to &quot;Per-slice&quot;">​</a></h3><ul><li>New entries as JSON under <code>static/data/missions/{body}/{id}.json</code> + <code>static/data/fleet/{category}/{id}.json</code> + both <code>index.json</code>.</li><li>Every entry: <code>id</code>, <code>name</code>, <code>agency</code>, <code>country</code>, <code>status</code>, <code>first_flight</code> (null if unflown), <code>best_known_for</code>, sourced <code>credit</code>, ≥3 <code>links</code>, <code>fleet_refs</code>/<code>linked_missions</code> symmetry.</li><li><strong>All 14 locale overlays</strong> authored via <code>scripts/translate-i18n-gaps.mjs</code> (i18n is core content).</li><li><code>npm run validate-data</code> + <code>npm run preflight</code> green.</li><li>Dates re-checked at slice start against the 2026-07-11 backlog; anything slipped &gt;6 months noted in <code>credit</code> rather than shipped stale.</li></ul><h3 id="v0-8-release-acceptance-bar-per-agency-completeness" tabindex="-1">v0.8 release acceptance bar (per-agency completeness) <a class="header-anchor" href="#v0-8-release-acceptance-bar-per-agency-completeness" aria-label="Permalink to &quot;v0.8 release acceptance bar (per-agency completeness)&quot;">​</a></h3><ul><li><strong>T1 + T2 landed</strong> across Slices 0–9 (T3 optional).</li><li>Per-agency coverage is <em>complete</em> for {NASA, US-commercial, CNSA, Roscosmos, ESA, JAXA, ISRO} — i.e. no <code>A</code>/<code>D</code> program element from the backlog missing without an explicit note.</li><li><code>surface-base</code> + <code>ground-observatory</code> filter chips live on <code>/fleet</code>.</li><li>Both backlog docs retained; this PRD moves Draft → Accepted (v0.8).</li></ul><h2 id="decisions-locked-2026-07-11" tabindex="-1">Decisions (LOCKED 2026-07-11) <a class="header-anchor" href="#decisions-locked-2026-07-11" aria-label="Permalink to &quot;Decisions (LOCKED 2026-07-11)&quot;">​</a></h2><ol><li><strong>Cut line:</strong> <strong>everything (T1+T2+T3), ~180+ entries.</strong> No silent deferrals.</li><li><strong><code>P</code> (proposed) policy:</strong> <strong>include</strong> proposed entries (Neptune orbiter, Venera-D, Yenisei, Mangalyaan-2, HWO, Interstellar Express, Enceladus Orbilander, …).</li><li><strong>Slice order (priority agencies first):</strong> <strong>NASA → China → Russia → ESA</strong> → JAXA → ISRO → newcomers/commercial → NASA planetary/CLPS → proposed tail. See the re-ordered slice plan above.</li><li><strong>Programs paradigm:</strong> adopt the <code>program</code> grouping layer (PRD-029) for all new entries, and retrofit historical missions/fleet.</li></ol><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><ul><li><strong>Date drift</strong> — most <code>NET 20xx</code> dates move; re-check per slice, flag &gt;6-month slips in <code>credit</code>.</li><li><strong>Thin newcomer sourcing</strong> — Vikram-1, VLM-1, KSLV-III, MBR lander, Turkish/African firsts lean on agency PRs + trade press; same editorial bar, source in native language + machine translation where needed (per project memory on global representation).</li><li><strong>Re-resets</strong> — NASA&#39;s Ignition reset won&#39;t be the last; a mid-slice pivot edits in-flight, not deferred.</li><li><strong><code>surface-base</code> ↔ <code>station</code> and <code>ILRS</code>-as-program ambiguity</strong> — name/describe ILRS + Moon Base as <em>programs</em>, not as a single finished object.</li><li><strong>14-locale load</strong> — i18n is now core content; the translate-pipeline pass is real per-entry cost, not a footnote.</li></ul><h2 id="source-of-truth-backlog" tabindex="-1">Source-of-truth backlog <a class="header-anchor" href="#source-of-truth-backlog" aria-label="Permalink to &quot;Source-of-truth backlog&quot;">​</a></h2><p><code>docs/research/forward-roadmap-2026-07-11.md</code> (comprehensive, per-agency, confidence-tagged, <code>→ entry-type</code> mapped) — compiled 2026-07-11 from 6 parallel research passes. Slice-time copy (<code>best_known_for</code>, <code>credit</code>, <code>links</code>) derives from it, not from cached training-data memory — these programs are too current. The 2026-06-09 backlog is retained as history.</p>`,35)])])}const m=a(n,[["render",s]]);export{g as __pageData,m as default};
